const out = [];
const chatId = $('Telegram Trigger').first().json.message.chat.id;
let raw = $input.first().json.output ?? $input.first().json.text ?? '';
let d;
try { d = JSON.parse(raw); } catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  try { d = JSON.parse(m[0]); } catch (e2) { d = { acao: 'conversa', resposta: 'Desculpa, nao entendi bem. Pode repetir?' }; }
}
const reply = d.resposta || 'Ok!';
if (d.acao === 'registrar' && Array.isArray(d.itens) && d.itens.length) {
  for (const p of d.itens) {
    const intencao = String(p.intencao || '').toLowerCase();
    const qtd = intencao === 'vou_comprar'
      ? (p.quantidade == null ? 0 : (Number(p.quantidade) || 0))
      : (Number(p.quantidade) || 1);
    out.push({ json: { acao: 'registrar', chat_id: chatId, agentReply: reply,
      intencao: intencao, item: p.item || '', marca: p.marca ?? null,
      preco: Number(p.preco) || 0, quantidade: qtd, unidade: p.unidade || 'un' } });
  }
} else if (d.acao === 'carrinho') {
  const op = String(d.op || '').toLowerCase();
  if (op === 'pegar' && Array.isArray(d.itens) && d.itens.length) {
    for (const p of d.itens) {
      const precoRaw = p.preco;
      const preco = (precoRaw === undefined || precoRaw === null || precoRaw === '') ? null : Number(precoRaw);
      out.push({ json: { acao: 'carrinho', op: 'pegar', chat_id: chatId, agentReply: reply,
        item: p.item || '', preco: preco, quantidade: Number(p.quantidade) || 1,
        unidade: p.unidade || 'un', confirmar: p.confirmar === true } });
    }
  } else {
    out.push({ json: { acao: 'carrinho', op: op, chat_id: chatId, agentReply: reply } });
  }
} else if (d.acao === 'criar_familia') {
  out.push({ json: { acao: 'criar_familia', chat_id: chatId, agentReply: reply, familia_nome: d.familia_nome || 'Minha casa' } });
} else if (d.acao === 'entrar_familia') {
  out.push({ json: { acao: 'entrar_familia', chat_id: chatId, agentReply: reply, codigo: d.codigo || '' } });
} else if (d.acao === 'consultar') {
  out.push({ json: { acao: 'consultar', chat_id: chatId, agentReply: reply, tipo: String(d.tipo || 'estoque').toLowerCase(), text: reply } });
} else {
  out.push({ json: { acao: 'conversa', chat_id: chatId, agentReply: reply, text: reply } });
}
return out;

const decItems = $('Decidir').all().map(i => i.json || {});
const rpcItems = $input.all().map(i => i.json || {});
const chatId = $('Telegram Trigger').first().json.message.chat.id;
function reais(n){ return 'R$ ' + (Number(n)||0).toFixed(2).replace('.', ','); }
function cap(s){ s = String(s||'').trim(); return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }
const linhas = [];
for (let idx = 0; idx < rpcItems.length; idx++) {
  const r = rpcItems[idx] || {};
  const d = decItems[idx] || {};
  if (r.ok === false && r.erro === 'sem_familia') {
    linhas.push('Você ainda não entrou numa família. Me diga "criar família" com um nome, ou "entrar" com o código de convite.');
    continue;
  }
  const nome = cap(d.item || r.item || 'Item');
  const marca = d.marca ? String(d.marca).trim() : '';
  const preco = Number(d.preco) || 0;
  const qtd = Number(d.quantidade) || 0;
  const unid = d.unidade || 'un';
  const intencao = String(d.intencao || '').toLowerCase();
  const qtdLabel = (unid && unid !== 'un') ? (qtd + ' ' + unid) : String(qtd);
  // ponytail: gênero pela última letra do nome (heurística cosmética; ajustar se incomodar)
  const genero = /a$/i.test(nome) ? 'a' : 'o';
  if (intencao === 'vou_comprar') {
    let l = '🛒 ' + nome + ' anotado na lista de compras';
    if (marca) l += ' (' + marca + ')';
    if (preco > 0) l += ' (~' + reais(preco) + ')';
    linhas.push(l);
  } else {
    const head = '✅ ' + nome + ' registrad' + genero + '!';
    const det = [];
    if (marca) det.push('Marca: ' + marca);
    if (preco > 0 && qtd > 1) det.push(qtdLabel + ' x ' + reais(preco) + ' = ' + reais(preco * qtd));
    else if (preco > 0) { det.push(reais(preco)); if (qtd > 1) det.push('Qtd: ' + qtdLabel); }
    else if (qtd > 1) det.push('Qtd: ' + qtdLabel);
    if (r.estoque_novo !== undefined && r.estoque_novo !== null) det.push('agora você tem ' + r.estoque_novo + ' em casa');
    if (r.economia !== undefined && Number(r.economia) > 0) det.push('💰 economizou ' + reais(r.economia));
    linhas.push(head + (det.length ? '\n' + det.join(' · ') : ''));
  }
}
const fallback = ($('Decidir').first().json || {}).agentReply || 'Feito.';
const text = linhas.length ? linhas.join('\n\n') : fallback;
return [{ json: { chat_id: chatId, text } }];

const items = $input.all();
const chatId = $('Rotear callback').first().json.callback_query.message.chat.id;
const prompt = 'Você recebe fotos de uma ou mais notas fiscais de supermercado do Brasil. Extraia os itens comprados. Responda SOMENTE um objeto JSON no formato {"itens":[{"nome":"","marca":"","qtd":0,"preco":0,"unidade":"un"}]}. Regras: nome = nome genérico do produto em minúsculas, sem marca (ex: "arroz", "leite", "sabão em pó"); marca = marca separada minúscula, ou "" se não houver; cada item aparece como DESCRICAO seguida de QTD x PRECO_UNITARIO (ex: 2 X 7,19 significa qtd 2 e preco 7.19); qtd = o numero inteiro ANTES do x (use 1 se nao houver x) e NUNCA use o preco como qtd (se o que voce leria como qtd for igual ao preco, use 1); preco = o valor APOS o x com ponto decimal; unidade = quase sempre "un", use "kg" apenas para granel por peso e "l" apenas para liquido vendido a granel, NUNCA use o peso ou volume do rotulo (por exemplo 800g, 500ml, 2l) como unidade nem como qtd. Ignore descontos, subtotais, total, impostos e linhas que não sejam produtos. Não invente itens.';
const content = [{ type: 'text', text: prompt }];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  content.push({ type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + buf.toString('base64') } });
}
// ponytail: modelo de visao real do Groq; troque aqui se quiser outro (era qwen/qwen3.6-27b no spec, inexistente)
const body = {
  model: 'meta-llama/llama-4-scout-17b-16e-instruct',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [{ role: 'user', content }]
};
return [{ json: { chat_id: chatId, body } }];

const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
const itens = parsed.itens || parsed.items || [];
const chatId = $('Rotear callback').first().json.callback_query.message.chat.id;
return [{ json: { chat_id: chatId, itens } }];

// Groq valida o tipo pela extensao do nome do arquivo. O Telegram baixa voz
// como .oga, que a Groq nao aceita; renomeia para .ogg (mesmo formato).
for (const item of $input.all()) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'audio.ogg';
    item.binary.data.fileExtension = 'ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
}
return $input.all();

const photos = $input.first().json.photos || [];
