const APP = 'https://mercado-mensal-app.vercel.app/';
const results = $input.all().map(i => i.json || {});
const decItems = $('Decidir').all().map(i => i.json || {});
function reais(n){ return 'R$ ' + (Number(n)||0).toFixed(2).replace('.', ','); }
function cap(s){ s = String(s||'').trim(); return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }
let text = '';
if (op === 'comecar') {
  const r = results[0] || {};
  text = (r.ok === false) ? (agentReply || 'Não consegui abrir a compra.')
       : '🛒 Compra aberta! Vá falando o que for pegando que eu vou somando o total.\nAcompanhe pelo painel: ' + APP;
} else if (op === 'pegar') {
  const linhas = [];
  let total = null;
  for (let idx = 0; idx < results.length; idx++) {
    const r = results[idx] || {};
    const d = decItems[idx] || {};
    if (r.ok === false && r.erro === 'sem_compra_aberta') { linhas.push('Você não está numa compra. Diga "tô no mercado" para começar.'); continue; }
    if (r.ok === false && r.erro === 'sem_preco') { linhas.push('Quanto foi o ' + cap(d.item || r.item || 'item') + '?'); continue; }
    if (r.needs_confirm === true) { linhas.push('Você já tem ' + r.estoque_atual + ' ' + (d.item || r.item) + ' em casa (acima do normal). Confirma que quer comprar mesmo assim?'); continue; }
    if (r.ok === true) {
      const nome = cap(d.item || r.item || 'Item');
      const marca = d.marca ? String(d.marca).trim() : '';
      const preco = Number(d.preco) || 0;
      const qtd = Number(d.quantidade) || 1;
      const unid = d.unidade || 'un';
      const qtdLabel = (unid && unid !== 'un') ? (qtd + ' ' + unid) : String(qtd);
      let l = '✅ ' + nome;
      if (marca) l += ' (' + marca + ')';
      if (preco > 0 && qtd > 1) l += ' · ' + qtdLabel + ' x ' + reais(preco) + ' = ' + reais(preco * qtd);
      else if (preco > 0) l += ' · ' + reais(preco);
      else if (qtd > 1) l += ' · ' + qtdLabel;
      linhas.push(l);
      if (r.total_parcial !== undefined && r.total_parcial !== null) total = r.total_parcial;
    }
  }
  if (total !== null) linhas.push('🧾 Total do carrinho: ' + reais(total));
  text = linhas.join('\n');
} else if (op === 'finalizar') {
  const r = results[0] || {};
  text = (r.ok === false) ? 'Você não está numa compra aberta.'
       : '🎉 Compra finalizada! ' + r.itens + ' itens, total ' + reais(r.total) + (r.economia > 0 ? '\n💰 Você economizou ' + reais(r.economia) : '') + '\nVeja no painel: ' + APP;
} else if (op === 'cancelar') {
  const r = results[0] || {};
  text = r.cancelada ? 'Compra cancelada.' : 'Não havia compra aberta.';
} else {
  text = agentReply || 'Feito.';
}
return [{ json: { chat_id: chatId, text: text || 'Feito.' } }];

